 if(interaction.customId==='belv_oral:launch'){
  await authorize(interaction.guild,interaction.user.id,interaction.channel);
  const select=new UserSelectMenuBuilder().setCustomId('belv_oral:candidate').setPlaceholder('Válaszd ki a vizsgázó Belv-tagot').setMinValues(1).setMaxValues(1);
  return interaction.reply({content:'Válaszd ki a jelöltet a szóbeli vizsga indításához.',components:[new ActionRowBuilder().addComponents(select)],flags:MessageFlags.Ephemeral});
 }
 const m=String(interaction.customId||'').match(/^belv_oral:(points|finish):(\d{1,19}):(\d{1,2})(?::(\d{1,10}))?$/);
 if(!m)return false;
 await authorize(interaction.guild,interaction.user.id,interaction.channel);
 const action=m[1],examId=m[2],page=Number(m[3]),revision=Number(m[4]||0);
